files.content:
* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

body {
  display: flex;
  justify-content: center;
  align-self: center;
  min-width: 850px;
  margin: 0;
  padding: 50px 0;
}

.container {
  width: 80%;
  max-width: 800px;
  font-size: 0;
  background-color: #feafe8;
}

.card {
  display: inline-block;
  width: calc(50% - 80px);
  height: 33.3%;
  margin-right: 80px;
  border: 1px solid #feafe8;
  background-color: #5f0dee;
}

.card:nth-child(even) {
  margin-right: 0;
  margin-left: 80px;
}
